(() => {
  "use strict";
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const state = { accounts: [], providers: [], schedules: [], resources: {}, logsPage: 1, logsTotal: 0, timer: null };
  const labels = { keyword_collect: "关键词采集", article_generate: "文章生成", article_publish: "文章发布", question_collect: "问题采集", answer_generate: "回答生成", answer_publish: "回答发布" };
  const statusLabels = { never: "未运行", running: "运行中", success: "成功", failed: "失败", skipped: "已跳过", pending: "等待中", completed: "完成", partial: "部分完成", paused: "暂停", stopped: "停止" };

  function esc(value) { const node = document.createElement("div"); node.textContent = value ?? ""; return node.innerHTML; }
  function toast(message, type = "success") { const node = document.createElement("div"); node.className = `toast ${type}`; node.textContent = message; $("#toast-region").append(node); setTimeout(() => node.remove(), 4500); }
  async function api(path, options = {}) { const token = sessionStorage.getItem("totod_token") || ""; const response = await fetch(`/api${path}`, { ...options, headers: { ...(options.body ? { "Content-Type": "application/json" } : {}), ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(options.headers || {}) } }); if (!response.ok) { let message = `请求失败（HTTP ${response.status}）`; try { const data = await response.json(); message = Array.isArray(data.detail) ? data.detail.map((item) => item.msg).join("；") : data.detail || message; } catch (_) {} throw new Error(message); } if (response.status === 204) return null; return response.json(); }
  function time(value) { if (!value) return "—"; return new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false }).format(new Date(value)); }
  function accountOptions(all = false) { return `${all ? '<option value="">全部知乎账号</option>' : '<option value="">请选择知乎账号</option>'}${state.accounts.map((item) => `<option value="${item.id}">${esc(item.display_name)}</option>`).join("")}`; }
  function providerOptions(config = {}) { const configured = state.providers.filter((item) => item.enabled && item.has_api_key); return configured.length ? configured.map((item) => `<option value="${item.provider}" data-model="${esc(item.model)}" ${config.provider === item.provider ? "selected" : ""}>${esc(item.display_name)} · ${esc(item.model)}</option>`).join("") : '<option value="">请先配置自己的 AI API</option>'; }

  async function loadBase() { try { const [accounts, providers] = await Promise.all([api("/accounts"), api("/ai/providers")]); state.accounts = accounts; state.providers = providers; ["#schedule-account"].forEach((id) => $(id).innerHTML = accountOptions(false)); ["#schedule-filter-account", "#logs-account"].forEach((id) => { const old = $(id).value; $(id).innerHTML = accountOptions(true); if (accounts.some((item) => item.id === old)) $(id).value = old; }); } catch (error) { if (!/登录|401/.test(error.message)) toast(error.message, "error"); } }
  async function accountResources(accountId) { if (!accountId) return { products: [], folders: [] }; if (!state.resources[accountId]) { const [products, folders] = await Promise.all([api(`/accounts/${accountId}/products?limit=500`), api(`/accounts/${accountId}/keyword-folders`)]); state.resources[accountId] = { products: products.items.filter((item) => item.enabled), folders }; } return state.resources[accountId]; }
  function numberField(id, label, value, min, max) { return `<div><label>${label}</label><input id="${id}" type="number" min="${min}" max="${max}" value="${value}" required></div>`; }
  async function renderDynamic(config = {}) { const type = $("#schedule-type").value; const accountId = $("#schedule-account").value; let resources = { products: [], folders: [] }; try { resources = await accountResources(accountId); } catch (error) { toast(error.message, "error"); } const products = resources.products.map((item) => `<option value="${item.id}" ${config.product_id === item.id ? "selected" : ""}>${esc(item.name)}</option>`).join(""); const folders = `<option value="">全部关键词</option>${resources.folders.map((item) => `<option value="${item.id}" ${config.folder_id === item.id ? "selected" : ""}>${esc(item.name)}（${item.keyword_count}）</option>`).join("")}`; let html = "";
    if (type === "keyword_collect") html = `<div class="field-grid"><div><label>主关键词</label><input id="sc-seed" value="${esc(config.seed_keyword || "")}" required></div><div><label>搜索引擎</label><select id="sc-source"><option value="both">百度 + 谷歌</option><option value="baidu">百度</option><option value="google">谷歌</option></select></div>${numberField("sc-target", "采集数量", config.target_count || 50, 1, 500)}<div><label>保存文件夹</label><select id="sc-folder">${folders}</select></div></div>`;
    if (type === "article_generate") html = `<div class="field-grid"><div><label>推广商品</label><select id="sc-product" required><option value="">请选择</option>${products}</select></div><div><label>AI 平台与模型</label><select id="sc-provider" required>${providerOptions(config)}</select></div><div><label>关键词文件夹</label><select id="sc-folder">${folders}</select></div>${numberField("sc-batch", "每次关键词数", config.batch_size || 10, 1, 50)}${numberField("sc-per", "每个词生成篇数", config.articles_per_keyword || 1, 1, 5)}${numberField("sc-min", "最少字数", config.min_length || 800, 100, 10000)}${numberField("sc-max", "最多字数", config.max_length || 1500, 100, 20000)}<div><label>生成后处理</label><select id="sc-output"><option value="draft">进入草稿箱</option><option value="immediate">立即发布</option></select></div></div>`;
    if (type === "article_publish") html = `<div class="field-grid">${numberField("sc-batch", "每次最多发布", config.batch_size || 3, 1, 100)}</div><p class="muted">只读取该账号“待发布”栏目，并受账号每日文章额度限制。</p>`;
    if (type === "question_collect") html = `<div class="field-grid"><div><label>触发关键词（每行一个）</label><textarea id="sc-keywords" required>${esc(Array.isArray(config.keywords) ? config.keywords.join("\n") : config.keywords || "")}</textarea></div>${numberField("sc-target", "每次采集数量", config.target_count || 20, 1, 100)}</div>`;
    if (type === "answer_generate") html = `<div class="field-grid"><div><label>推广商品</label><select id="sc-product" required><option value="">请选择</option>${products}</select></div><div><label>AI 平台与模型</label><select id="sc-provider" required>${providerOptions(config)}</select></div>${numberField("sc-batch", "每次问题数", config.batch_size || 10, 1, 50)}${numberField("sc-min", "最少字数", config.min_length || 300, 100, 5000)}${numberField("sc-max", "最多字数", config.max_length || 800, 100, 10000)}<label class="toggle-row"><input id="sc-ready" type="checkbox" ${config.ready_after_generate === false ? "" : "checked"}>生成后进入待发布</label></div>`;
    if (type === "answer_publish") html = '<p class="muted">按该账号每日回答额度，自动发布“待发布”回答。成功和失败尝试均计入当天额度。</p>';
    $("#schedule-dynamic").innerHTML = html; if ($("#sc-source")) $("#sc-source").value = config.source || "both"; if ($("#sc-output")) $("#sc-output").value = config.output_mode || "draft";
  }
  function collectConfig() { const type = $("#schedule-type").value; const value = (id) => $(id)?.value; const number = (id) => Number(value(id)); if (type === "keyword_collect") return { seed_keyword: value("#sc-seed"), source: value("#sc-source"), target_count: number("#sc-target"), folder_id: value("#sc-folder") || null }; if (type === "article_generate") { const provider = $("#sc-provider"); return { product_id: value("#sc-product"), provider: value("#sc-provider"), model: provider.selectedOptions[0]?.dataset.model || "", folder_id: value("#sc-folder") || null, batch_size: number("#sc-batch"), articles_per_keyword: number("#sc-per"), min_length: number("#sc-min"), max_length: number("#sc-max"), output_mode: value("#sc-output") }; } if (type === "article_publish") return { batch_size: number("#sc-batch") }; if (type === "question_collect") return { keywords: value("#sc-keywords").split(/[\n,，;；]+/).map((item) => item.trim()).filter(Boolean), target_count: number("#sc-target") }; if (type === "answer_generate") { const provider = $("#sc-provider"); return { product_id: value("#sc-product"), provider: value("#sc-provider"), model: provider.selectedOptions[0]?.dataset.model || "", batch_size: number("#sc-batch"), min_length: number("#sc-min"), max_length: number("#sc-max"), ready_after_generate: $("#sc-ready").checked }; } return {}; }

  async function loadSchedules() { const params = new URLSearchParams(); if ($("#schedule-filter-account").value) params.set("account_id", $("#schedule-filter-account").value); try { state.schedules = await api(`/schedules?${params}`); renderSchedules(); } catch (error) { toast(error.message, "error"); } }
  function renderSchedules() { $("#schedule-count").textContent = `共 ${state.schedules.length} 个计划`; $("#schedule-empty").hidden = state.schedules.length > 0; $("#schedule-list").innerHTML = state.schedules.map((item) => `<div class="operation-table operation-schedule-row" data-id="${item.id}"><div><strong>${esc(item.name)}</strong><small>${esc(item.account_name)}</small></div><span>${labels[item.task_type] || item.task_type}</span><span>${String(item.hour).padStart(2, "0")}:${String(item.minute).padStart(2, "0")} · ${item.weekdays.length === 7 ? "每天" : item.weekdays.map((day) => "一二三四五六日"[day]).join("、")}</span><span class="badge ${item.last_status === "success" ? "ok" : item.last_status === "failed" ? "danger" : "off"}">${statusLabels[item.last_status] || item.last_status}</span><span>${time(item.next_run_at)}<small>${esc(item.last_message || "尚未执行")}</small></span><div class="operation-actions"><button class="button button-primary schedule-run">立即运行</button><button class="button button-ghost schedule-toggle">${item.enabled ? "停用" : "启用"}</button><button class="button button-ghost schedule-edit">编辑</button><button class="button button-ghost danger-text schedule-delete">删除</button></div></div>`).join(""); $$(".schedule-run").forEach((button) => button.addEventListener("click", () => runNow(button.closest("[data-id]").dataset.id))); $$(".schedule-toggle").forEach((button) => button.addEventListener("click", () => toggleSchedule(button.closest("[data-id]").dataset.id))); $$(".schedule-edit").forEach((button) => button.addEventListener("click", () => editSchedule(button.closest("[data-id]").dataset.id))); $$(".schedule-delete").forEach((button) => button.addEventListener("click", () => deleteSchedule(button.closest("[data-id]").dataset.id))); }
  async function openEditor(item = null) { $("#schedule-form").reset(); $("#schedule-id").value = item?.id || ""; $("#schedule-editor-title").textContent = item ? "编辑定时计划" : "新建定时计划"; $("#schedule-account").disabled = Boolean(item); $("#schedule-type").disabled = Boolean(item); if (item) { $("#schedule-name").value = item.name; $("#schedule-account").value = item.account_id; $("#schedule-type").value = item.task_type; $("#schedule-time").value = `${String(item.hour).padStart(2, "0")}:${String(item.minute).padStart(2, "0")}`; $("#schedule-enabled").checked = item.enabled; $$(".weekday-picker input").forEach((box) => box.checked = item.weekdays.includes(Number(box.value))); } else { $("#schedule-enabled").checked = true; $$(".weekday-picker input").forEach((box) => box.checked = true); } await renderDynamic(item?.config || {}); $("#schedule-editor").hidden = false; $("#schedule-error").textContent = ""; }
  function closeEditor() { $("#schedule-editor").hidden = true; }
  function editSchedule(id) { openEditor(state.schedules.find((item) => item.id === id)); }
  async function saveSchedule(event) { event.preventDefault(); const id = $("#schedule-id").value; const [hour, minute] = $("#schedule-time").value.split(":").map(Number); const weekdays = $$(".weekday-picker input:checked").map((box) => Number(box.value)); if (!weekdays.length) return $("#schedule-error").textContent = "至少选择一个星期"; const body = { name: $("#schedule-name").value, enabled: $("#schedule-enabled").checked, hour, minute, weekdays, config: collectConfig() }; if (!id) { body.account_id = $("#schedule-account").value; body.task_type = $("#schedule-type").value; } try { await api(id ? `/schedules/${id}` : "/schedules", { method: id ? "PATCH" : "POST", body: JSON.stringify(body) }); closeEditor(); await loadSchedules(); toast(id ? "计划已保存" : "计划已创建"); } catch (error) { $("#schedule-error").textContent = error.message; } }
  async function toggleSchedule(id) { const item = state.schedules.find((value) => value.id === id); try { await api(`/schedules/${id}`, { method: "PATCH", body: JSON.stringify({ enabled: !item.enabled }) }); await loadSchedules(); } catch (error) { toast(error.message, "error"); } }
  async function runNow(id) { try { await api(`/schedules/${id}/run`, { method: "POST" }); toast("计划已开始执行"); setTimeout(loadSchedules, 1000); } catch (error) { toast(error.message, "error"); } }
  async function deleteSchedule(id) { if (!confirm("确定删除这个定时计划吗？")) return; try { await api(`/schedules/${id}`, { method: "DELETE" }); await loadSchedules(); toast("计划已删除"); } catch (error) { toast(error.message, "error"); } }

  async function loadLogs() { const params = new URLSearchParams({ limit: "100", offset: String((state.logsPage - 1) * 100) }); if ($("#logs-account").value) params.set("account_id", $("#logs-account").value); if ($("#logs-category").value) params.set("category", $("#logs-category").value); if ($("#logs-search").value.trim()) params.set("q", $("#logs-search").value.trim()); try { const data = await api(`/operation-logs?${params}`); state.logsTotal = data.total; $("#logs-empty").hidden = data.total > 0; $("#logs-list").innerHTML = data.items.map((item) => `<div class="operation-table operation-log-row"><div><strong>${esc(item.task_name)}</strong><small>${time(item.started_at)}${item.completed_at ? ` → ${time(item.completed_at)}` : ""}</small></div><span>${esc(item.account_name || "—")}</span><span class="badge ${["completed", "success"].includes(item.status) ? "ok" : ["failed", "partial"].includes(item.status) ? "danger" : "off"}">${statusLabels[item.status] || item.status}</span><span>${item.total_count}</span><span>${item.success_count} / ${item.failed_count}</span><span class="operation-message">${esc(item.message || "—")}</span></div>`).join(""); const pages = Math.max(1, Math.ceil(data.total / 100)); $("#logs-pagination").hidden = data.total <= 100; $("#logs-page-info").textContent = `第 ${state.logsPage} / ${pages} 页 · 共 ${data.total} 条`; $("#logs-prev").disabled = state.logsPage <= 1; $("#logs-next").disabled = state.logsPage >= pages; } catch (error) { toast(error.message, "error"); } }
  async function exportLogs() { const token = sessionStorage.getItem("totod_token") || ""; try { const response = await fetch("/api/operation-logs/export", { headers: token ? { Authorization: `Bearer ${token}` } : {} }); if (!response.ok) throw new Error("导出失败"); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `totod-logs-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(url); } catch (error) { toast(error.message, "error"); } }
  async function loadSettings() { try { const item = await api("/system-settings"); $("#setting-log-days").value = item.log_retention_days; $("#setting-timezone").value = item.default_timezone; $("#setting-interval-min").value = item.publish_interval_min; $("#setting-interval-max").value = item.publish_interval_max; $("#setting-browser-timeout").value = item.browser_timeout_seconds; } catch (error) { if (!/403|权限/.test(error.message)) toast(error.message, "error"); } }
  async function saveSettings(event) { event.preventDefault(); const body = { log_retention_days: Number($("#setting-log-days").value), default_timezone: $("#setting-timezone").value, publish_interval_min: Number($("#setting-interval-min").value), publish_interval_max: Number($("#setting-interval-max").value), browser_timeout_seconds: Number($("#setting-browser-timeout").value) }; try { await api("/system-settings", { method: "PUT", body: JSON.stringify(body) }); $("#settings-error").textContent = ""; toast("系统设置已保存"); } catch (error) { $("#settings-error").textContent = error.message; } }
  async function activate(page) { await loadBase(); if (page === "schedules") await loadSchedules(); if (page === "logs") await loadLogs(); if (page === "settings") await loadSettings(); }
  function bind() { $("#schedule-new").addEventListener("click", () => openEditor()); $("#schedule-editor-close").addEventListener("click", closeEditor); $("#schedule-cancel").addEventListener("click", closeEditor); $("#schedule-form").addEventListener("submit", saveSchedule); $("#schedule-type").addEventListener("change", () => renderDynamic()); $("#schedule-account").addEventListener("change", () => renderDynamic()); $("#schedule-filter-account").addEventListener("change", loadSchedules); $("#logs-refresh").addEventListener("click", loadLogs); $("#logs-account").addEventListener("change", () => { state.logsPage = 1; loadLogs(); }); $("#logs-category").addEventListener("change", () => { state.logsPage = 1; loadLogs(); }); let searchTimer; $("#logs-search").addEventListener("input", () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { state.logsPage = 1; loadLogs(); }, 300); }); $("#logs-prev").addEventListener("click", () => { state.logsPage--; loadLogs(); }); $("#logs-next").addEventListener("click", () => { state.logsPage++; loadLogs(); }); $("#logs-export").addEventListener("click", exportLogs); $("#system-settings-form").addEventListener("submit", saveSettings); $$("[data-page]").forEach((button) => button.addEventListener("click", () => { if (["schedules", "logs", "settings"].includes(button.dataset.page)) setTimeout(() => activate(button.dataset.page), 50); })); $("#login-form").addEventListener("submit", () => setTimeout(loadBase, 900)); }
  document.addEventListener("DOMContentLoaded", () => { bind(); loadBase(); state.timer = setInterval(() => { const page = $(".nav-item.active")?.dataset.page; if (page === "schedules") loadSchedules(); }, 15000); });
})();
